/**
 * Message an Agent Node - Version 3.1
 * Send a message to a n8n agent
 */


export interface MessageAnAgentV31Params {
  agentSource?: unknown;
/**
 * The agent to send the message to
 * @displayOptions.show { agentSource: ["referenced"] }
 * @default {"__rl":true,"mode":"list","value":""}
 */
    agentId?: { __rl: true; mode: 'list' | 'id'; value: string | number; cachedResultName?: string; cachedResultUrl?: string } | Expression<string>;
  inlineAgent?: unknown;
/**
 * The message to send to the agent
 */
    message: string | Expression<string>;
/**
 * Whether to constrain the agent response to a JSON Schema you provide. The conforming object is returned on the "structuredOutput" field.
 * @default false
 */
    useStructuredOutput?: boolean | Expression<boolean>;
/**
 * How to specify the structured output schema
 * @displayOptions.show { useStructuredOutput: [true] }
 * @default fromJson
 */
    schemaType?: 'fromJson' | 'manual';
/**
 * Example JSON object used to generate the output schema
 * @displayOptions.show { useStructuredOutput: [true], schemaType: ["fromJson"] }
 */
    jsonSchemaExample?: IDataObject | string;
/**
 * The JSON Schema that the agent response must conform to
 * @hint Use &lt;a target="_blank" href="https://json-schema.org/"&gt;JSON Schema&lt;/a&gt; format
 * @displayOptions.show { useStructuredOutput: [true], schemaType: ["manual"] }
 */
    outputSchema?: IDataObject | string | Expression<string>;
  advanced?: {
    /** Whether to stream the agent's response as it generates text
     * @default true
     */
    enableStreaming?: boolean | Expression<boolean>;
    /** Whether to call the agent once per input item or a single time for all items
     * @displayOptions.hide { /agentSource: ["inline"] }
     * @default allItems
     */
    invokeMode?: 'allItems' | 'perItem';
    /** Session
     * @default {"session":{}}
     */
    session?: {
        /** Session
     */
    session?: {
      /** Session ID
       * @default fromInput
       */
      sessionIdType?: 'fromInput' | 'customKey' | Expression<string>;
      /** Session Key From Previous Node
       * @displayOptions.show { sessionIdType: ["fromInput", "customKey"] }
       * @default ={{ $json.sessionId }}
       */
      sessionKey?: string | Expression<string>;
    };
  };
    /** Whether to give the agent a tool to read other workflow nodes' execution data, beyond its own input
     * @displayOptions.hide { /agentSource: ["inline"] }
     * @default false
     */
    allowOtherNodesData?: boolean | Expression<boolean>;
  };
}

export type MessageAnAgentV31Output = {
  text: string;
  structuredOutput: unknown;
  usage: {
    promptTokens?: number;
    completionTokens?: number;
    totalTokens?: number;
  } | null;
  toolCalls: Array<{
    toolName?: string;
    input?: unknown;
    result?: unknown;
  }>;
  finishReason: string;
  session: {
    agentId?: string;
    projectId?: string;
    sessionId?: string;
    threadId?: string;
  } | null;
};

interface MessageAnAgentV31NodeBase {
  type: 'n8n-nodes-base.messageAnAgent';
  version: 3.1;
}

export type MessageAnAgentV31ParamsNode = MessageAnAgentV31NodeBase & {
  config: NodeConfig<MessageAnAgentV31Params>;
  output?: Items<MessageAnAgentV31Output>;
};

export type MessageAnAgentV31Node = MessageAnAgentV31ParamsNode;